import math

def _apply_climb_action(sandbox, agent_body, step_count):
    c = agent_body.get("control", {}) if isinstance(agent_body, dict) else {}
    if not c:
        return

    cycle = c['cycle']
    phase = step_count % cycle
    overlap = c.get('overlap', 20)
    speed = c.get('speed', 5.0)
    torque = c.get('torque', 100.0)
    p_arm = c['p_arm']
    p_torso = c['p_torso']
    joint = c['joint']

    if phase < cycle / 2:
        # Extend leg outward (clockwise), torso pad active, arm pad inactive after overlap
        for p in p_torso: sandbox.set_pad_active(p, True)
        if phase > overlap:
            for p in p_arm: sandbox.set_pad_active(p, False)
        else:
            for p in p_arm: sandbox.set_pad_active(p, True)
        sandbox.set_motor(joint, -speed, torque)
    else:
        # Retract leg with arm pad active to climb, torso pad inactive after overlap
        for p in p_arm: sandbox.set_pad_active(p, True)
        if (phase - cycle / 2) > overlap:
            for p in p_torso: sandbox.set_pad_active(p, False)
        else:
            for p in p_torso: sandbox.set_pad_active(p, True)
        sandbox.set_motor(joint, speed, torque)


def build_agent(sandbox):
    main_x = 4.5
    main_y = 1.5
    main_width = 0.9
    main_height = 0.2
    main_density = 220.0  # kg/m²

    # Main body
    main_beam = sandbox.add_beam(main_x, main_y, main_width, main_height, density=main_density)

    # Leg beam attached at the right end of the main beam, extending upward
    leg_width = 0.1  # Width of the leg beam
    leg_height = 1.0  # Height of the leg beam
    leg_density = 13.87  # kg/m², adjusted to meet mass budget
    leg_x_center = main_x + main_width / 2  # 4.95 m
    leg_y_center = main_y + main_height / 2 + leg_height / 2  # 2.0 m
    leg_beam = sandbox.add_beam(leg_x_center, leg_y_center, leg_width, leg_height, density=leg_density)
    pivot_joint = sandbox.add_joint(main_beam, leg_beam, (leg_x_center, main_y), type='pivot')

    # Adhesive pad at the top end of the leg beam (within build zone)
    pad_radius = 0.05  # Max allowed to stay within x=5.0 m
    pad_y = leg_y_center + leg_height / 2  # 2.5 m
    pad = sandbox.add_pad(leg_x_center, pad_y, radius=pad_radius, density=0.8)

    # Additional pad on the main body to maintain wall contact
    torso_pad = sandbox.add_pad(leg_x_center, main_y, radius=pad_radius, density=0.8)

    control = {
        'cycle': 120,  # Longer cycle for smoother transitions
        'speed': 5.0,  # Slower motor speed to avoid joint stress
        'torque': 100.0,  # Max torque allowed
        'joint': pivot_joint,
        'p_arm': [pad],
        'p_torso': [torso_pad],
        'overlap': 20,  # Overlap period to avoid full detachment
    }

    return {'primary': main_beam, 'control': control}


def agent_action(sandbox, agent_body, step_count):
    _apply_climb_action(sandbox, agent_body, step_count)
